export function cleanFeatureText(str){return String(str||"").toLowerCase().replace(/[.,;:!?()[\]{}"'`]/g," ").replace(/\s+/g," ").trim()}export function removeVietnameseAccents(str){return String(str||"").normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/đ/g,"d").replace(/Đ/g,"D")}const TRAILING_WORDS=new Set(["nhe","nha","a","di","voi","giup","anh","em","nhi","khong","chua","ha","roi","oi"]);export const KNOWN_SHAPES=[{shape:"tam giac",match:/\b(?:tam giac|triangle)\b/i},{shape:"chu nhat",match:/\b(?:chu nhat|rectangle|chu\s+nhat)\b/i},{shape:"oval",match:/\b(?:oval|bau duc|ellipse)\b/i},{shape:"vuong",match:/\b(?:vuong|square)\b/i},{shape:"tron",match:/\b(?:tron|round|circular)\b/i}];export function extractShapeKeyword(text){const norm=removeVietnameseAccents(cleanFeatureText(text));for(const item of KNOWN_SHAPES){if(item.match.test(norm)){return item.shape}}const words=norm.split(/\s+/).filter(w=>!["lo","hole","holes","cai","hinh","co","than"].includes(w)&&!TRAILING_WORDS.has(w));return words.join(" ").trim()}export function parseSingleFeature(segment){const raw=String(segment||"").trim();if(!raw)return null;const cleaned=cleanFeatureText(raw);const match=cleaned.match(/^(\d+)\s*(.+)$/);if(match){const num=parseInt(match[1],10);const textPart=match[2].trim();return{number:num,text:textPart,shape:extractShapeKeyword(textPart),raw:raw}}const innerMatch=cleaned.match(/(\d+)\s+([a-zA-Zà-ỹÀ-Ỹ\s]+)/);if(innerMatch){const num=parseInt(innerMatch[1],10);const textPart=innerMatch[2].trim();return{number:num,text:textPart,shape:extractShapeKeyword(textPart),raw:raw}}return{number:null,text:cleaned,shape:extractShapeKeyword(cleaned),raw:raw}}export function parseIdentifyingFeatures(featuresString){if(!featuresString)return[];const segments=String(featuresString).split(",").map(s=>s.trim()).filter(Boolean);const results=[];for(const seg of segments){if(seg.includes("+")){const plusParts=seg.split("+").map(p=>p.trim()).filter(Boolean);for(const pp of plusParts){const pf=parseSingleFeature(pp);if(pf&&pf.number!=null){results.push(pf)}}}const parsed=parseSingleFeature(seg);if(parsed){results.push(parsed)}}return results}export function extractQueryFeatures(queryMessage){const msg=String(queryMessage||"").trim();if(!msg)return[];if(msg.includes(",")){const commaParts=msg.split(",").map(p=>p.trim()).filter(Boolean);const candidateParts=[];for(const part of commaParts){const parsed=parseSingleFeature(part);if(parsed&&(parsed.number!=null||parsed.shape)){candidateParts.push(parsed)}else{const sub=extractQueryFeatures(part);if(sub.length)candidateParts.push(...sub)}}if(candidateParts.length>0){return candidateParts}}const results=[];const pattern=/(?:^|[^\d])(\d+)\s*(?:lo|lỗ|hole|holes)?\s*([a-zA-Zà-ỹÀ-Ỹ]+(?:\s+[a-zA-Zà-ỹÀ-Ỹ]+)?)/gi;let m;const regex=new RegExp(pattern);while((m=regex.exec(msg))!==null){const num=parseInt(m[1],10);const textPart=m[2].trim();const cleaned=cleanFeatureText(textPart);const stopwords=["ngay","thang","nam","gio","phut","lan","con","ma","chiec","dong","trang"];if(stopwords.includes(removeVietnameseAccents(cleaned))){continue}const fullText=`lỗ ${cleaned}`;results.push({number:num,text:fullText,shape:extractShapeKeyword(fullText),raw:m[0].trim()})}if(results.length===0){const directParsed=parseSingleFeature(msg);if(directParsed&&directParsed.number!=null&&directParsed.text.length>0){results.push(directParsed)}}return results}export function isSingleFeatureMatch(dbFeature,queryFeature){if(!dbFeature||!queryFeature)return false;if(queryFeature.number!=null){if(dbFeature.number==null||dbFeature.number!==queryFeature.number){return false}}const qShape=queryFeature.shape||extractShapeKeyword(queryFeature.text);const dbShape=dbFeature.shape||extractShapeKeyword(dbFeature.text);if(qShape){if(!dbShape)return false;if(qShape!==dbShape){return false}return true}const dbText=removeVietnameseAccents(cleanFeatureText(dbFeature.text));const qText=removeVietnameseAccents(cleanFeatureText(queryFeature.text));if(dbText===qText||dbText.includes(qText)||qText.includes(dbText)){return true}return false}export function parseIdentifyingFeaturesAST(text){const raw=String(text||"").trim();if(!raw){return{totalHoles:null,bigHoles:null,smallHoles:null,holeShapes:[],otherNumberedPairs:[],keywords:[]}}const cleaned=cleanFeatureText(raw);const norm=removeVietnameseAccents(cleaned);let totalHoles=null;let bigHoles=null;let smallHoles=null;const holeShapes=[];const otherNumberedPairs=[];const keywords=[];const bigMatch=norm.match(/(?:^|[^\d])(\d+)\s*(?:(?:lo\s*(?:tron\s*)?|lo\s+)?(?:to|lon)\b|(?:to|lon)\b)/i);if(bigMatch){bigHoles=parseInt(bigMatch[1],10)}const smallMatch=norm.match(/(?:^|[^\d])(\d+)\s*(?:(?:lo\s*(?:tron\s*)?|lo\s+)?(?:nho|be)\b|(?:nho|be)\b)/i);if(smallMatch){smallHoles=parseInt(smallMatch[1],10)}const totalRegex=/(?:^|[^\d])(\d+)\s*(?:lo|hole|holes)\b(?!\s*(?:to|lon|nho|be))/gi;let tMatch;while((tMatch=totalRegex.exec(norm))!==null){const n=parseInt(tMatch[1],10);if(totalHoles==null){totalHoles=n}}if(totalHoles==null){const directShapeMatch=norm.match(/(?:^|[^\d])(\d+)\s*(?:tron|vuong|oval|bau duc|chu nhat|tam giac)\b/i);if(directShapeMatch){totalHoles=parseInt(directShapeMatch[1],10)}}if(totalHoles==null&&bigHoles!=null&&smallHoles!=null){totalHoles=bigHoles+smallHoles}else if(totalHoles==null&&bigHoles!=null&&smallHoles==null){totalHoles=bigHoles}else if(totalHoles==null&&smallHoles!=null&&bigHoles==null){totalHoles=smallHoles}else if(totalHoles!=null&&bigHoles!=null&&smallHoles==null&&totalHoles>=bigHoles){smallHoles=totalHoles-bigHoles}else if(totalHoles!=null&&smallHoles!=null&&bigHoles==null&&totalHoles>=smallHoles){bigHoles=totalHoles-smallHoles}for(const item of KNOWN_SHAPES){if(item.match.test(norm)){if(!holeShapes.includes(item.shape)){holeShapes.push(item.shape)}}}const pairRegex=/(?:^|[^\d])(\d+)\s+([a-zA-Zà-ỹÀ-Ỹ]+)/gi;let pMatch;while((pMatch=pairRegex.exec(cleaned))!==null){const num=parseInt(pMatch[1],10);const noun=pMatch[2].trim().toLowerCase();const nounNorm=removeVietnameseAccents(noun);const isHoleWord=["lo","lỗ","to","lon","nho","be","tron","vuong","oval"].includes(nounNorm);const isStopWord=["ngay","thang","nam","gio","phut","lan","con","ma","chiec","dong","trang"].includes(nounNorm);if(!isHoleWord&&!isStopWord){otherNumberedPairs.push({count:num,noun:nounNorm})}}const STRUCTURAL_KEYWORDS=["uon cong","dap noi","vat goc","tai bat oc","go dap","gan noi","dap gan","chot dinh vi","ngam"];for(const kw of STRUCTURAL_KEYWORDS){if(norm.includes(kw)){keywords.push(kw)}}return{totalHoles:totalHoles,bigHoles:bigHoles,smallHoles:smallHoles,holeShapes:holeShapes,otherNumberedPairs:otherNumberedPairs,keywords:keywords}}export function matchFeatureQueryFlexible(dbText,queryText){if(!dbText||!queryText){return{matched:false,tier:"none",score:0}}if(queryText.includes(",")){const parts=queryText.split(",").map(p=>p.trim()).filter(Boolean);if(parts.length>1){let minScore=1;let worstTier="exact_match";for(const part of parts){const sub=matchFeatureQueryFlexible(dbText,part);if(!sub.matched){return{matched:false,tier:"none",score:0}}if(sub.score<minScore)minScore=sub.score;if(sub.tier==="perceptual_tolerance")worstTier="perceptual_tolerance";else if(sub.tier==="partial_match"&&worstTier!=="perceptual_tolerance")worstTier="partial_match"}return{matched:true,tier:worstTier,score:minScore}}}const dbAST=parseIdentifyingFeaturesAST(dbText);const qAST=parseIdentifyingFeaturesAST(queryText);const qHasHoleNumber=qAST.totalHoles!=null||qAST.bigHoles!=null||qAST.smallHoles!=null;const qHasOtherNumber=qAST.otherNumberedPairs.length>0;const qHasKeywords=qAST.keywords.length>0;const qHasShapes=qAST.holeShapes.length>0;if(!qHasHoleNumber&&!qHasOtherNumber&&!qHasKeywords&&!qHasShapes){return{matched:false,tier:"none",score:0}}if(qHasShapes){if(dbAST.holeShapes.length>0){const allShapesMatch=qAST.holeShapes.every(qs=>dbAST.holeShapes.includes(qs));if(!allShapesMatch){return{matched:false,tier:"none",score:0}}}else{const normDb=removeVietnameseAccents(cleanFeatureText(dbText));for(const qs of qAST.holeShapes){const shapeItem=KNOWN_SHAPES.find(s=>s.shape===qs);if(shapeItem&&!shapeItem.match.test(normDb)){return{matched:false,tier:"none",score:0}}}}}for(const qPair of qAST.otherNumberedPairs){const matchedPair=dbAST.otherNumberedPairs.find(dbPair=>dbPair.count===qPair.count&&(dbPair.noun.includes(qPair.noun)||qPair.noun.includes(dbPair.noun)));if(!matchedPair){return{matched:false,tier:"none",score:0}}}const normDb=removeVietnameseAccents(cleanFeatureText(dbText));for(const kw of qAST.keywords){if(!normDb.includes(kw)){return{matched:false,tier:"none",score:0}}}if(qHasHoleNumber){if(qAST.totalHoles!=null){if(dbAST.totalHoles==null||dbAST.totalHoles!==qAST.totalHoles){return{matched:false,tier:"none",score:0}}if(qAST.bigHoles!=null&&qAST.smallHoles!=null){if(dbAST.bigHoles!=null&&dbAST.smallHoles!=null){if(qAST.bigHoles===dbAST.bigHoles&&qAST.smallHoles===dbAST.smallHoles){return{matched:true,tier:"exact_match",score:1}}if(Math.abs(qAST.bigHoles-dbAST.bigHoles)===1&&Math.abs(qAST.smallHoles-dbAST.smallHoles)===1){return{matched:true,tier:"perceptual_tolerance",score:.85}}return{matched:false,tier:"none",score:0}}return{matched:true,tier:"partial_match",score:.9}}if(qAST.bigHoles!=null){if(dbAST.bigHoles!=null){if(qAST.bigHoles===dbAST.bigHoles){return{matched:true,tier:"exact_match",score:1}}if(Math.abs(qAST.bigHoles-dbAST.bigHoles)===1){return{matched:true,tier:"perceptual_tolerance",score:.85}}return{matched:false,tier:"none",score:0}}return{matched:true,tier:"partial_match",score:.9}}if(qAST.smallHoles!=null){if(dbAST.smallHoles!=null){if(qAST.smallHoles===dbAST.smallHoles){return{matched:true,tier:"exact_match",score:1}}if(Math.abs(qAST.smallHoles-dbAST.smallHoles)===1){return{matched:true,tier:"perceptual_tolerance",score:.85}}return{matched:false,tier:"none",score:0}}return{matched:true,tier:"partial_match",score:.9}}return{matched:true,tier:"exact_match",score:1}}if(qAST.bigHoles!=null){if(dbAST.bigHoles!=null){if(qAST.bigHoles===dbAST.bigHoles){return{matched:true,tier:"exact_match",score:1}}if(Math.abs(qAST.bigHoles-dbAST.bigHoles)===1){return{matched:true,tier:"perceptual_tolerance",score:.85}}}return{matched:false,tier:"none",score:0}}if(qAST.smallHoles!=null){if(dbAST.smallHoles!=null){if(qAST.smallHoles===dbAST.smallHoles){return{matched:true,tier:"exact_match",score:1}}if(Math.abs(qAST.smallHoles-dbAST.smallHoles)===1){return{matched:true,tier:"perceptual_tolerance",score:.85}}}return{matched:false,tier:"none",score:0}}return{matched:false,tier:"none",score:0}}if(qHasShapes||qHasKeywords||qHasOtherNumber){return{matched:true,tier:"partial_match",score:.8}}return{matched:false,tier:"none",score:0}}export function matchRowWithFeatures(row,queryFeatures,rawQuery=""){if(!row)return false;if(rawQuery){const flex=matchFeatureQueryFlexible(row.identifying_features,rawQuery);if(flex.matched)return true}if(Array.isArray(queryFeatures)&&queryFeatures.length>0){const queryStr=queryFeatures.map(q=>q.raw||`${q.number||""} ${q.text||""}`).join(", ");const flex=matchFeatureQueryFlexible(row.identifying_features,queryStr);if(flex.matched)return true}if(!queryFeatures||queryFeatures.length===0)return false;const dbFeatures=parseIdentifyingFeatures(row.identifying_features);if(dbFeatures.length===0)return false;for(const qf of queryFeatures){const matched=dbFeatures.some(df=>isSingleFeatureMatch(df,qf));if(!matched){return false}}return true}export function filterCatalogueByQueryFeatures(catalogueRows,queryMessage){const queryFeatures=extractQueryFeatures(queryMessage);const qAST=parseIdentifyingFeaturesAST(queryMessage);const hasAST=qAST.totalHoles!=null||qAST.bigHoles!=null||qAST.smallHoles!=null||qAST.holeShapes.length>0;if(queryFeatures.length===0&&!hasAST){return{isFeatureQuery:false,queryFeatures:[],matchedRows:[]}}const rows=Array.isArray(catalogueRows)?catalogueRows:[];const matchedRows=rows.filter(row=>matchRowWithFeatures(row,queryFeatures,queryMessage));return{isFeatureQuery:true,queryFeatures:queryFeatures,matchedRows:matchedRows}}